      IF (IOPT .GE. 100) GO TO 140
      DO 131 I = 3,6
      IF (NPVT .EQ. NECPT(I)) GO TO 140
  131 CONTINUE
      IF (KOUNT.EQ.NGPT .AND. JTYPE.NE.0) GO TO 910
